"""Description-only pricing. Isolation Forest removes exactly half the training rows."""
from pathlib import Path
import json,numpy as np,pandas as pd
from sklearn.ensemble import IsolationForest,ExtraTreesRegressor
from common import metrics
root=Path(__file__).resolve().parents[1];cache=root/'training-cache';dist=root/'dist';d=pd.read_json(cache/'dense-cohort.jsonl',lines=True);x=np.load(cache/'e5-descriptions.npy');y=d.price.to_numpy(float);tr=np.flatnonzero(d.phase=='train');va=np.flatnonzero(d.phase=='validation');te=np.flatnonzero(d.phase=='test');iso=IsolationForest(n_estimators=300,contamination=.5,max_samples=min(256,len(tr)),random_state=42,n_jobs=8).fit(x[tr]);scores=iso.score_samples(x[tr]);order=np.argsort(-scores,kind='stable');keep=tr[order[:len(tr)//2]];removed=tr[order[len(tr)//2:]];choices=[]
for leaf in [2,5,10]:
 for fraction in [.25,1.]:
  fit=ExtraTreesRegressor(n_estimators=200,min_samples_leaf=leaf,max_features=fraction,random_state=42,n_jobs=8).fit(x[keep],np.log1p(y[keep]));pred=np.expm1(fit.predict(x[va]));score=float(np.mean(abs(y[va]-pred)));choices.append((score,leaf,fraction,fit));print('validation',leaf,fraction,score,flush=True)
score,leaf,fraction,fit=min(choices,key=lambda a:a[0]);pred=np.expm1(fit.predict(x[te]));q=float(np.quantile(abs(np.log1p(y[va])-fit.predict(x[va])),.8,method='higher'));coverage=float(np.mean(abs(np.log1p(y[te])-fit.predict(x[te]))<=q));old=json.loads((dist/'pricing-model.json').read_text())['meta'];encoder_meta_path=cache/'encoder-meta.json';encoder_meta=json.loads(encoder_meta_path.read_text()) if encoder_meta_path.exists() else old['description_encoder'];meta={'description_encoder':encoder_meta,'max_characters':8000,'canonical_cohort_rows':10892,'period':'April–May 2021','price_min':1000,'price_max':150000,'target':'log1p USD asking price','date_ranges':{phase:[str(d.loc[d.phase==phase,'date'].min()),str(d.loc[d.phase==phase,'date'].max())] for phase in ['train','validation','test']},'form_validation':'Held-out metrics evaluate original seller descriptions; generated GUI descriptions are not separately validated.'};meta.update(architecture='E5-large description only → Isolation Forest training filter → Extra Trees regression',encoder='embaas/sentence-transformers-multilingual-e5-large',total_dimensions=1024,usable_rows=len(d),pilot=len(d)<10892,trained_rows=len(keep),training_candidates=len(tr),training_removed=len(removed),removed_fraction=len(removed)/len(tr),validation_rows=len(va),test_rows=len(te),outlier_filter={'algorithm':'IsolationForest','contamination':.5,'training_only':True,'exact_half_by_score_ranking':True,'price_used_in_filter':False,'estimators':300},regressor={'algorithm':'ExtraTreesRegressor','estimators':200,'min_samples_leaf':leaf,'max_features':fraction,'target':'log1p price','selection':'validation USD MAE'},evaluation={'description_forest':{'validation_mae_usd':score,'test':metrics(y[te],pred)}},band80_log_residual=q,band80_test_coverage=coverage,evaluation_scope='Pilot evaluation; remove half of training candidates only. Validation/test are unfiltered. Not directly comparable to previous full-cohort runs.',filter_warning='Semantic anomaly is not evidence that a listing is incorrect. Removing 50% can discard valid rare vehicles and bias coverage.')
trees=[]
for estimator in fit.estimators_:
 t=estimator.tree_;trees.append({'left':t.children_left.tolist(),'right':t.children_right.tolist(),'feature':t.feature.tolist(),'threshold':[float(v) for v in t.threshold],'value':t.value[:,0,0].tolist()})
bundle={'meta':meta,'forest':trees};(dist/'pricing-model.json').write_text(json.dumps(bundle,separators=(',',':')));(dist/'evaluation.json').write_text(json.dumps(meta,indent=2));pd.DataFrame({'canonical_row':tr,'anomaly_score':scores,'kept':np.isin(tr,keep)}).to_csv(cache/'isolation-filter.csv',index=False);pd.DataFrame({'actual_price':y[te],'prediction':pred}).to_csv(cache/'forest-test-predictions.csv',index=False)
fixtures=[{'embedding':x[i].tolist(),'expected_log':float(fit.predict(x[i:i+1])[0])} for i in [0,len(d)-1]];(dist/'head-fixtures.json').write_text(json.dumps(fixtures));print(json.dumps(meta,indent=2),flush=True)
